'use strict';

// MODULES //

var logger = require( 'debug' );
var join = require( '@stdlib/array/base/join' );
var lowercase = require( '@stdlib/string/lowercase' );
var format = require( '@stdlib/string/format' );
var classifyHTML = require( './classify_html.js' );
var diagnostic = require( './diagnostic.js' );
var account = require( './account.js' );


// VARIABLES //

var debug = logger( 'markdown-to-semantic-document:structure' );


// FUNCTIONS //

/**
* Returns a structural section key.
*
* @private
* @param {string} name - section class name
* @returns {string} section key
*/
function sectionKey( name ) {
	var value = lowercase( name );

	// Keep conventional class names readable in IDs; encode unusual values so the resulting path remains unambiguous and JSON-safe...
	if ( /^[a-z0-9_-]+$/.test( value ) ) {
		return value;
	}
	return encodeURIComponent( value );
}

/**
* Returns a new internal structural section.
*
* @private
* @param {Object} parent - parent structural node
* @param {Object} node - section opening node
* @param {string} role - section role
* @returns {Object} structural section
*/
function section( parent, node, role ) {
	var ordinal;
	var key;
	var id;

	key = sectionKey( role );

	// Ordinals are local to the parent and role. Prefixing a parent ID makes nested section identities deterministic without requiring source offsets...
	ordinal = parent.sectionCounts[ key ] || 0;
	id = format( 'section[%s:%s]', key, ordinal );
	parent.sectionCounts[ key ] = ordinal + 1;
	if ( parent.id ) {
		id = format( '%s/%s', parent.id, id );
	}
	debug( 'Created structural section: id=%s role=%s ordinal=%d parent=%s', id, role, ordinal, parent.id || 'document' );
	return {
		'type': 'section',
		'id': id,
		'role': role,
		'path': parent.path.concat( role ),
		'ordinal': ordinal,
		'openingNode': node,
		'closingNode': null,
		'endNode': null,
		'rawChildren': [],
		'sectionCounts': Object.create( null ),
		'parent': parent,
		'recovered': false
	};
}


// MAIN //

/**
* Recovers a nested section hierarchy from root MDAST children.
*
* @private
* @param {Object} tree - MDAST tree
* @param {Object} state - conversion state
* @returns {Object} internal document structure
*/
function structure( tree, state ) {
	var classification;
	var sectionNode;
	var lastClosed;
	var current;
	var stack;
	var child;
	var root;
	var i;

	lastClosed = null;
	root = {
		'type': 'document',
		'id': '',
		'path': [],
		'rawChildren': [],
		'sectionCounts': Object.create( null ),
		'parent': null
	};

	debug( 'Recovering document structure: profile=%s rootChildren=%d', state.options.profile, tree.children.length );
	current = root;
	stack = [ root ];
	if ( state.options.profile === 'generic' ) {
		// Generic Markdown does not assign semantics to stdlib's HTML section idiom, so leave every root child untouched for the normal conversion pass...
		root.rawChildren = tree.children.slice();
		debug( 'Skipped stdlib structure recovery for generic profile.' );
		return root;
	}

	// Process each root MDAST child while maintaining the stack of currently open semantic sections...
	for ( i = 0; i < tree.children.length; i++ ) {
		child = tree.children[ i ];
		if ( child.type !== 'html' ) {
			// Non-HTML content belongs to the currently open structural section...
			current.rawChildren.push( child );
			lastClosed = null;
			continue;
		}
		classification = classifyHTML( child.value );
		if ( classification.type === 'section-open' ) {
			// Insert a structural placeholder in source order, then make it the target for subsequent root MDAST nodes until a close is encountered...
			sectionNode = section( current, child, classification.name );

			debug( 'Opening structural section: id=%s depth=%d', sectionNode.id, stack.length );
			current.rawChildren.push( sectionNode );
			if ( sectionNode.ordinal > 0 && state.options.profile !== 'generic' ) {
				diagnostic( state, 'warning', 'duplicate-section', format( 'Section `%s` occurs more than once in the same parent.', classification.name ), child, {
					'role': classification.name,
					'ordinal': sectionNode.ordinal
				});
			}
			account( state, child, 'consumed-as-structure', 'section-open', 'Opened semantic section.', [ sectionNode.id ] );
			stack.push( sectionNode );
			current = sectionNode;
			lastClosed = null;
			continue;
		}
		if ( classification.type === 'section-close' ) {
			if ( stack.length === 1 ) {
				// An unmatched close cannot contribute structure. Mark it for raw-flow preservation so that permissive conversion remains lossless...
				debug( 'Encountered unmatched structural section close: astPath=%s', join( state.provenance.path( child ), '.' ) );
				state.forceRaw[ join( state.provenance.path( child ), '.' ) ] = (
					'unmatched-section-close'
				);
				current.rawChildren.push( child );
				diagnostic( state, 'error', 'unmatched-section-close', 'Encountered a section closing tag without a matching opening tag.', child );
				lastClosed = null;
				continue;
			}
			// A closing tag always closes the innermost section; slash-dot comments provide the named confirmation used to detect mismatches afterward...
			debug( 'Closing structural section: id=%s depth=%d', current.id, stack.length-1 );
			current.closingNode = child;
			account( state, child, 'consumed-as-structure', 'section-close', 'Closed semantic section.', [ current.id ] );
			lastClosed = current;
			stack.pop();
			current = stack[ stack.length-1 ];
			continue;
		}
		if ( classification.type === 'section-end' ) {
			if ( lastClosed && lastClosed.role === classification.name ) {
				// Normal case: the named marker confirms the section just closed...
				debug( 'Confirming structural section close: id=%s', lastClosed.id );
				lastClosed.endNode = child;
				account( state, child, 'consumed-as-structure', 'section-end', 'Confirmed semantic section close.', [ lastClosed.id ] );
			} else if (
				current !== root &&
				current.role === classification.name
			) {
				// Recover a missing `</section>` at a matching named marker. Popping here prevents the following sibling section from being nested accidentally...
				debug( 'Recovering structural section at named end marker: id=%s', current.id );
				current.endNode = child;
				current.recovered = true;
				account( state, child, 'consumed-as-structure', 'section-end', 'Recovered a semantic section missing its closing tag.', [ current.id ] );
				diagnostic( state, 'error', 'unclosed-section', format( 'Section `%s` is missing a closing tag and was recovered at its section end comment.', current.role ), current.openingNode, {
					'role': current.role,
					'recoveredAt': state.provenance.path( child )
				});
				lastClosed = current;
				stack.pop();
				current = stack[ stack.length-1 ];
			} else {
				// A mismatched marker is evidence, not structure. Preserve it verbatim and continue using the current stack so a later real close can still recover...
				debug( 'Encountered mismatched structural section end marker: role=%s', classification.name );
				state.forceRaw[ join( state.provenance.path( child ), '.' ) ] = (
					'mismatched-section-end-comment'
				);
				current.rawChildren.push( child );
				diagnostic( state, 'error', 'mismatched-section-end-comment', 'Section end comment does not match the preceding closed section.', child, {
					'role': classification.name,
					'closedRole': ( lastClosed ) ? lastClosed.role : null
				});
			}
			continue;
		}
		current.rawChildren.push( child );
		lastClosed = null;
	}
	// End-of-file recovery leaves section content usable while recording every unclosed wrapper as an error diagnostic...
	while ( stack.length > 1 ) {
		current = stack.pop();
		debug( 'Recovering unclosed structural section at end of input: id=%s', current.id );
		current.recovered = true;
		diagnostic( state, 'error', 'unclosed-section', format( 'Section `%s` is not closed.', current.role ), current.openingNode, {
			'role': current.role
		});
	}
	debug( 'Recovered document structure: rootChildren=%d diagnostics=%d', root.rawChildren.length, state.document.diagnostics.length );
	return root;
}


// EXPORTS //

module.exports = structure;
